begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000005420','web-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000005421','web-staff@example.test',now());
insert into auth.users(id,is_anonymous) values
 ('f0000000-0000-4000-8000-000000005422',true),
 ('f0000000-0000-4000-8000-000000005423',true);
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005420","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Weblink queue','weblink-queue-test',gen_random_uuid())::text,true);
select set_config('test.other_tenant',create_tenant('Other queue','weblink-other-test',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','seller@web.test','')::text,true);
select set_config('test.printer',gen_random_uuid()::text,true);
select set_config('test.legacy',gen_random_uuid()::text,true);
select register_printer(current_setting('test.tenant')::uuid,current_setting('test.legacy')::uuid,'Windows','tcp','192.0.2.1','',203);
-- Future onboarding is intentionally absent. Only this fixture seeds Weblink.
reset role;
insert into public.printers(id,tenant_id,name,transport,address,created_by)
 values(current_setting('test.printer')::uuid,current_setting('test.tenant')::uuid,'Weblink','weblink','','f0000000-0000-4000-8000-000000005420');
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000005421','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005420","role":"authenticated"}';
select set_config('test.code',create_print_pairing_code(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid)->>'code',true);
select throws_like($$select register_printer(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,'Weblink','tcp','192.0.2.1','',203)$$,'%PRINT_TRANSPORT_FIXED%','a Weblink printer cannot become a legacy printer');
select throws_ok($$select claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,gen_random_uuid())$$,'42501',null,'staff authority is not a device send permit');
select set_config('test.job',gen_random_uuid()::text,true);
select queue_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.printer')::uuid,'onboarding','zpl-v1','seller',current_setting('test.seller')::uuid,'^XA^FDFixture^FS^XZ',2);
select throws_like($$select claim_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid)$$,'%WEBLINK_REQUIRED%','legacy member consumer cannot claim Weblink');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005422","role":"authenticated","is_anonymous":true}';
select set_config('test.device',pair_print_device(current_setting('test.code'),'Bridge','test')->>'deviceId',true);
select is((select count(*) from print_jobs),0::bigint,'device still cannot read job tables');
select throws_like($$select claim_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid)$$,'%WEBLINK_REQUIRED%','legacy device consumer cannot claim Weblink');
select throws_ok($$select claim_weblink_print_job(current_setting('test.other_tenant')::uuid,current_setting('test.printer')::uuid,gen_random_uuid())$$,'42501',null,'wrong store refused');
select throws_ok($$select claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.legacy')::uuid,gen_random_uuid())$$,'42501',null,'wrong printer refused');
select set_config('test.attempt',gen_random_uuid()::text,true);
select set_config('test.claim',claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,current_setting('test.attempt')::uuid)::text,true);
select is(current_setting('test.claim')::jsonb->>'jobId',current_setting('test.job'),'one job reserved');
select is(current_setting('test.claim')::jsonb->>'canSend','true','first response grants one send');
select is(current_setting('test.claim')::jsonb->>'payload','^XA^FDFixture^FS^XZ','exact ZPL');
select is((current_setting('test.claim')::jsonb->>'copies')::int,2,'exact copies');
select is(claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,current_setting('test.attempt')::uuid)->>'canSend','false','lost claim reply never grants a second send');
select ok(not (claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,current_setting('test.attempt')::uuid) ? 'payload'),'recovery does not disclose printable payload');
select is(claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,gen_random_uuid()),null,'different attempt cannot reclaim reserved work');
select throws_like($$select complete_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,true)$$,'%WEBLINK_REQUIRED%','old completion API cannot label Weblink output printed');
select throws_like($$select finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,gen_random_uuid(),'transport_accepted')$$,'%PRINT_ATTEMPT_CONFLICT%','wrong attempt refused');
select throws_like($$select finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.attempt')::uuid,'printed')$$,'%INVALID_INPUT%','a device cannot assert physical printing');
-- Age does not release an uncertain send, even after a server restart.
reset role;
alter table public.print_jobs disable trigger print_jobs_guard;
update print_jobs set claimed_at=now()-interval '1 day' where id=current_setting('test.job')::uuid;
alter table public.print_jobs enable trigger print_jobs_guard;
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005422","role":"authenticated","is_anonymous":true}';
select is(claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,gen_random_uuid()),null,'stale Weblink attempt is never released');
select is(finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.attempt')::uuid,'outcome_unknown'),current_setting('test.job')::uuid,'uncertain outcome persisted');
select is(finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.attempt')::uuid,'outcome_unknown'),current_setting('test.job')::uuid,'same outcome replay is safe');
select throws_like($$select finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.attempt')::uuid,'transport_accepted')$$,'%PRINT_JOB_DECIDED%','conflicting outcome cannot overwrite uncertainty');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005421","role":"authenticated"}';
select throws_ok($$select resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'cancelled','Inspected the printer')$$,'42501',null,'staff cannot resolve uncertainty');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005420","role":"authenticated"}';
select is((select status from print_jobs where id=current_setting('test.job')::uuid),'outcome_unknown','unknown is visible to the store');
select throws_like($$select resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'cancelled','Inspected the printer')$$,'%PRINT_DEVICE_STILL_ACTIVE%','recovery needs a revoked device');
select revoke_print_device(current_setting('test.tenant')::uuid,current_setting('test.device')::uuid);
select throws_like($$select resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'cancelled','')$$,'%INVALID_INPUT%','recovery requires an inspection note');
select throws_like($$select resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'queued','Inspected the printer')$$,'%INVALID_INPUT%','recovery cannot reset the job to queued');
select is(resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'cancelled','Inspected and stopped the old connection'),current_setting('test.job')::uuid,'owner abandons the old job explicitly');
select is(resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'cancelled','Inspected and stopped the old connection'),current_setting('test.job')::uuid,'same recovery replays');
select throws_like($$select resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'printed','Inspected')$$,'%PRINT_JOB_DECIDED%','changed resolution refused');
select is((select dispatch_attempt::text from print_jobs where id=current_setting('test.job')::uuid),current_setting('test.attempt'),'recovery retains dispatch provenance');
select is((select count(*) from print_jobs where printer_id=current_setting('test.printer')::uuid),1::bigint,'recovery does not create a retry');
select is((select count(*) from access_events where tenant_id=current_setting('test.tenant')::uuid and action='print.dispatch_resolved'),1::bigint,'repeated recovery appends only one audit record');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005422","role":"authenticated","is_anonymous":true}';
select throws_ok($$select finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.attempt')::uuid,'transport_accepted')$$,'42501',null,'revoked worker cannot alter recovery');
select throws_ok($$select claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,gen_random_uuid())$$,'42501',null,'revoked device cannot claim');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005420","role":"authenticated"}';
select set_config('test.code2',create_print_pairing_code(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid)->>'code',true);
select set_config('test.job2',gen_random_uuid()::text,true);
select queue_print_job(current_setting('test.tenant')::uuid,current_setting('test.job2')::uuid,current_setting('test.printer')::uuid,'onboarding','zpl-v1','seller',current_setting('test.seller')::uuid,'^XA^FDNew^FS^XZ',1);
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005423","role":"authenticated","is_anonymous":true}';
select set_config('test.device2',pair_print_device(current_setting('test.code2'),'Replacement','test')->>'deviceId',true);
select throws_like($$select finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.attempt')::uuid,'transport_accepted')$$,'%PRINT_ATTEMPT_CONFLICT%','replacement device cannot decide the old attempt');
select throws_like($$select claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,current_setting('test.attempt')::uuid)$$,'%PRINT_ATTEMPT_CONFLICT%','old attempt cannot be transferred to a replacement device');
select set_config('test.attempt2',gen_random_uuid()::text,true);
select is(claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,current_setting('test.attempt2')::uuid)->>'jobId',current_setting('test.job2'),'replacement can claim a newly requested job');
select is(finish_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job2')::uuid,current_setting('test.attempt2')::uuid,'transport_accepted'),current_setting('test.job2')::uuid,'transport acceptance recorded');
select throws_ok($$update print_jobs set status='printed' where id=current_setting('test.job2')::uuid$$,'42501',null,'device cannot update evidence directly');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005420","role":"authenticated"}';
select is((select status from print_jobs where id=current_setting('test.job2')::uuid),'transport_accepted','transport completion does not mean printed');
select revoke_print_device(current_setting('test.tenant')::uuid,current_setting('test.device2')::uuid);
select is(resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job2')::uuid,'printed','Physically inspected the label and stopped the connection'),current_setting('test.job2')::uuid,'owner records observed physical output');
select is((select dispatch_resolved_by::text from print_jobs where id=current_setting('test.job2')::uuid),'f0000000-0000-4000-8000-000000005420','physical confirmation retains the human actor');
reset role;
select throws_like($$update print_jobs set dispatch_attempt=gen_random_uuid() where id=current_setting('test.job2')::uuid$$,'%IMMUTABLE_PRINT_JOB%','privileged edits outside the engine are refused');
set local role anon;
select throws_ok($$select claim_weblink_print_job(gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'42501',null,'anonymous callers have no RPC grant');
reset role;
select * from finish();
rollback;
